#include <stddef.h>
#include <stdint.h>
int64_t lee_breadth_first_search(const int64_t*v,size_t n){if(!v||n<6||n>70)return -2;int64_t rows=v[0],cols=v[1],sr=v[2],sc=v[3],dr=v[4],dc=v[5];if(rows<1||rows>8||cols<1||cols>8||n!=6+(size_t)(rows*cols)||sr<0||sr>=rows||dr<0||dr>=rows||sc<0||sc>=cols||dc<0||dc>=cols)return -2;int64_t cell[64],dist[64],q[64];for(int64_t i=0;i<rows*cols;i++){cell[i]=v[6+i];if(cell[i]!=0&&cell[i]!=1)return -2;dist[i]=-1;}int64_t s=sr*cols+sc,t=dr*cols+dc;if(cell[s]==0||cell[t]==0)return -1;size_t h=0,z=0;dist[s]=0;q[z++]=s;while(h<z){int64_t u=q[h++];if(u==t)return dist[u];int64_t r=u/cols,c=u%cols;int64_t rr[4]={r-1,r,r,r+1},cc[4]={c,c-1,c+1,c};for(int k=0;k<4;k++)if(rr[k]>=0&&rr[k]<rows&&cc[k]>=0&&cc[k]<cols){int64_t w=rr[k]*cols+cc[k];if(cell[w]==1&&dist[w]<0){dist[w]=dist[u]+1;q[z++]=w;}}}return -1;}
